#!/usr/bin/env python3
"""Draws the flat SVG illustrations in public/img/work (original artwork for this project).
Run once: python3 scripts/draw-work-icons.py"""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / 'public' / 'img' / 'work'
OUT.mkdir(parents=True, exist_ok=True)

BG = lambda c: f'<rect width="64" height="64" rx="8" fill="{c}"/>'
PERSON = lambda x, y, shirt='#e63946', skin='#f5c6a5': f'<circle cx="{x}" cy="{y}" r="5" fill="{skin}"/><path d="M{x - 5} {y - 1} Q{x} {y - 8} {x + 5} {y - 1}" fill="#5a2d1a"/><rect x="{x - 6}" y="{y + 5}" width="12" height="14" rx="3" fill="{shirt}"/>'
BOX = lambda x, y, w=20, h=14: f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="1" fill="#c97b63" stroke="#8d5524"/><rect x="{x}" y="{y + h / 2 - 1}" width="{w}" height="2" fill="#8d5524"/>'
DOC = lambda x, y, w=20, h=26: f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="1" fill="#fff" stroke="#999"/>' + ''.join(f'<rect x="{x + 3}" y="{y + 5 + i * 5}" width="{w - 6 - (i % 2) * 4}" height="2" fill="#bbb"/>' for i in range(4))
ARROW = lambda x1, y1, x2, y2, c='#222': f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{c}" stroke-width="2.5"/><circle cx="{x2}" cy="{y2}" r="2.5" fill="{c}"/>'
DESK = '<rect x="6" y="40" width="52" height="4" fill="#8d5524"/><rect x="10" y="44" width="4" height="12" fill="#5a2d1a"/><rect x="50" y="44" width="4" height="12" fill="#5a2d1a"/>'
LAPTOP = lambda x, y: f'<rect x="{x}" y="{y}" width="22" height="14" rx="1" fill="#222"/><rect x="{x + 2}" y="{y + 2}" width="18" height="10" fill="#8ecae6"/><rect x="{x - 2}" y="{y + 14}" width="26" height="2" fill="#555"/>'
STAR = lambda x, y, c='#ffd54a', s=1: f'<polygon transform="translate({x} {y}) scale({s})" points="0,-6 1.8,-1.8 6,-1.4 2.8,1.6 3.7,6 0,3.6 -3.7,6 -2.8,1.6 -6,-1.4 -1.8,-1.8" fill="{c}"/>'

ICONS = {
    'be-laid-off': BG('#eceff1') + BOX(8, 38) + PERSON(44, 16, '#607d8b') + '<path d="M30 26 L36 20 M36 26 L30 20" stroke="#c62828" stroke-width="3"/><rect x="10" y="12" width="20" height="8" rx="1" fill="#fff" stroke="#999"/><text x="20" y="18" font-family="sans-serif" font-size="5" fill="#c62828" text-anchor="middle">CLOSED</text>' + ARROW(44, 38, 56, 50, '#c62828'),
    'get-a-degree': BG('#e8eaf6') + PERSON(32, 24, '#3949ab') + '<rect x="22" y="12" width="20" height="4" fill="#222"/><rect x="26" y="8" width="12" height="4" fill="#222"/><line x1="42" y1="14" x2="44" y2="22" stroke="#ffd54a" stroke-width="1.5"/>' + '<rect x="40" y="40" width="18" height="6" rx="3" fill="#fff" stroke="#999"/><rect x="47" y="39" width="4" height="8" fill="#e63946"/>',
    'take-a-training-course': BG('#e0f2f1') + '<rect x="6" y="8" width="36" height="24" fill="#2e7d32"/><rect x="8" y="10" width="32" height="20" fill="#388e3c"/><text x="24" y="23" font-family="sans-serif" font-size="7" fill="#fff" text-anchor="middle">COURSE</text>' + PERSON(50, 20, '#4d96ff') + PERSON(14, 46, '#e63946') + PERSON(30, 46, '#ff9800', '#c68642') + PERSON(46, 46, '#9c27b0'),
    'get-a-job': BG('#e8f5e9') + PERSON(20, 16, '#4d96ff') + PERSON(46, 16, '#222') + '<path d="M26 34 Q33 28 40 34" stroke="#f5c6a5" stroke-width="4" fill="none"/>' + DOC(22, 42, 20, 16) + '<text x="32" y="53" font-family="sans-serif" font-size="5" fill="#2e7d32" text-anchor="middle">HIRED</text>',
    'retire': BG('#fff8e1') + PERSON(26, 18, '#795548', '#f5c6a5') + '<path d="M21 17 Q26 12 31 17" fill="#ddd"/><rect x="10" y="30" width="30" height="14" rx="4" fill="#8d5524"/><path d="M8 44 Q6 54 12 56 M42 44 Q44 54 38 56" stroke="#5a2d1a" stroke-width="3" fill="none"/><circle cx="52" cy="14" r="7" fill="#ffd54a"/><path d="M44 48 Q52 36 60 48" stroke="#4caf50" stroke-width="3" fill="none"/>',
    'get-a-promotion': BG('#fff3e0') + '<rect x="8" y="44" width="14" height="12" fill="#ffb74d"/><rect x="25" y="34" width="14" height="22" fill="#ff9800"/><rect x="42" y="22" width="14" height="34" fill="#f57c00"/>' + PERSON(49, 8, '#222') + ARROW(14, 40, 40, 16, '#2e7d32') + STAR(10, 12),
    'do-an-internship': BG('#e3f2fd') + DESK + LAPTOP(30, 26) + PERSON(16, 20, '#4d96ff') + DOC(8, 46, 14, 12) + '<rect x="4" y="6" width="26" height="8" rx="2" fill="#4d96ff"/><text x="17" y="12" font-family="sans-serif" font-size="5.5" fill="#fff" text-anchor="middle">INTERN</text>',
    'resign': BG('#fce4ec') + DESK + PERSON(44, 16, '#9c27b0') + DOC(12, 22, 20, 18) + '<text x="22" y="34" font-family="sans-serif" font-size="4.5" fill="#c62828" text-anchor="middle">I QUIT</text>' + '<path d="M44 46 L44 56 M40 56 L48 56" stroke="#222" stroke-width="2"/>' + ARROW(50, 30, 60, 30, '#c62828'),
    'look-for-a-job': BG('#f1f8e9') + '<rect x="8" y="10" width="34" height="42" fill="#fff" stroke="#999"/><text x="25" y="20" font-family="sans-serif" font-size="6" font-weight="bold" fill="#222" text-anchor="middle">JOBS</text>' + ''.join(f'<rect x="12" y="{25 + i * 6}" width="{26 - (i % 2) * 8}" height="2" fill="#bbb"/>' for i in range(4)) + '<circle cx="46" cy="40" r="10" fill="none" stroke="#333" stroke-width="3"/><line x1="53" y1="47" x2="60" y2="54" stroke="#333" stroke-width="4"/><circle cx="46" cy="40" r="7" fill="#8ecae6" opacity=".5"/>',
    'learn-new-skills': BG('#ede7f6') + PERSON(20, 36, '#673ab7') + '<rect x="34" y="34" width="22" height="16" fill="#fff" stroke="#999"/><rect x="36" y="36" width="18" height="2" fill="#bbb"/><rect x="36" y="40" width="14" height="2" fill="#bbb"/><rect x="36" y="44" width="16" height="2" fill="#bbb"/>' + '<circle cx="20" cy="14" r="7" fill="#ffd54a"/><rect x="17" y="21" width="6" height="4" fill="#999"/><path d="M14 10 L10 6 M26 10 L30 6 M20 4 L20 2" stroke="#ffd54a" stroke-width="2"/>' + '<text x="45" y="26" font-family="sans-serif" font-size="7" fill="#673ab7" text-anchor="middle">&lt;/&gt;</text>',
    'get-experience': BG('#fffde7') + PERSON(32, 16, '#ff9800', '#c68642') + STAR(10, 48, '#ffd54a') + STAR(21, 48, '#ffd54a') + STAR(32, 48, '#ffd54a') + STAR(43, 48, '#ffd54a') + STAR(54, 48, '#ccc') + '<text x="32" y="61" font-family="sans-serif" font-size="5.5" fill="#555" text-anchor="middle">5 years</text>',
    'get-fired': BG('#ffebee') + DESK + PERSON(18, 14, '#222') + '<path d="M26 26 L40 30" stroke="#f5c6a5" stroke-width="4"/>' + PERSON(48, 20, '#607d8b') + BOX(40, 46, 18, 10) + '<rect x="4" y="30" width="22" height="8" rx="2" fill="#c62828"/><text x="15" y="36" font-family="sans-serif" font-size="5.5" fill="#fff" text-anchor="middle">YOU’RE OUT</text>',
    'do-a-job-placement': BG('#e0f7fa') + '<rect x="6" y="20" width="24" height="30" fill="#4d96ff"/><rect x="10" y="24" width="6" height="6" fill="#fff59d"/><rect x="20" y="24" width="6" height="6" fill="#fff59d"/><rect x="10" y="34" width="6" height="6" fill="#fff59d"/><rect x="20" y="34" width="6" height="6" fill="#fff59d"/><rect x="14" y="42" width="8" height="8" fill="#222"/>' + PERSON(48, 20, '#4caf50') + ARROW(44, 44, 32, 44, '#2e7d32') + '<rect x="40" y="48" width="18" height="8" rx="1" fill="#fff" stroke="#999"/><text x="49" y="54" font-family="sans-serif" font-size="4.5" fill="#222" text-anchor="middle">3 months</text>',
    'freelance': BG('#f3e5f5') + '<rect x="6" y="44" width="52" height="4" fill="#8d5524"/>' + LAPTOP(22, 30) + PERSON(46, 18, '#9c27b0') + '<circle cx="14" cy="18" r="6" fill="#fff" stroke="#999"/><path d="M14 14 L14 18 L17 20" stroke="#222" stroke-width="1.5" fill="none"/><path d="M8 30 Q14 26 20 30" stroke="#4caf50" stroke-width="2" fill="none"/>',
    'unemployed': BG('#eceff1') + PERSON(32, 18, '#9e9e9e') + '<path d="M18 38 Q14 44 8 42" stroke="#f5c6a5" stroke-width="3" fill="none"/><path d="M46 38 Q50 44 56 42" stroke="#f5c6a5" stroke-width="3" fill="none"/>' + DOC(22, 40, 20, 16) + '<path d="M26 44 L38 52 M38 44 L26 52" stroke="#c62828" stroke-width="2.5"/><path d="M29 17 L35 17" stroke="#222" stroke-width="1.5"/>',
}

for name, body in ICONS.items():
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">{body}</svg>'
    (OUT / f'{name}.svg').write_text(svg)
